export type TransactionKind = "buy" | "sell" | "opening-balance" | "fee" | "dividend";

export interface TransactionSource {
  fileName: string;
  rowNumber: number;
}

export interface CanonicalTransaction {
  /** Stable source ID or deterministic ID generated by an importer. */
  transactionId: string;
  kind: TransactionKind;
  /** Required for security-specific trades/opening balances; optional for portfolio-level fees/dividends. */
  instrumentId?: string;
  occurredAt: string;
  currency: string;
  quantity?: number;
  unitPrice?: number;
  /** Cash amount for fee/dividend rows, in the transaction currency. */
  amount?: number;
  /** Optional transaction charges attached to a trade, in the transaction currency. */
  charges?: number;
  source: TransactionSource;
}

export interface TransactionIssue {
  field: string;
  message: string;
}

export type TransactionValidation =
  | { status: "valid"; transaction: CanonicalTransaction }
  | { status: "invalid"; issues: TransactionIssue[] };

const transactionKinds: readonly TransactionKind[] = [
  "buy",
  "sell",
  "opening-balance",
  "fee",
  "dividend",
];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isPositiveFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value > 0;
}

function isNonNegativeFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

/**
 * Runtime validation boundary for imported/user-provided transaction data.
 * It reports issues instead of dropping malformed rows or filling defaults.
 */
export function validateTransaction(input: unknown): TransactionValidation {
  if (!isRecord(input)) {
    return {
      status: "invalid",
      issues: [{ field: "transaction", message: "Transaction must be an object." }],
    };
  }

  const issues: TransactionIssue[] = [];
  const addIssue = (field: string, message: string) => issues.push({ field, message });

  if (typeof input.transactionId !== "string" || !input.transactionId.trim()) {
    addIssue("transactionId", "A stable transaction ID is required.");
  }

  if (typeof input.kind !== "string" || !transactionKinds.includes(input.kind as TransactionKind)) {
    addIssue("kind", "Transaction kind is unsupported.");
  }

  const kind = input.kind as TransactionKind;
  const instrumentId = input.instrumentId;
  if (
    ["buy", "sell", "opening-balance"].includes(kind) &&
    (typeof instrumentId !== "string" || !instrumentId.trim())
  ) {
    addIssue("instrumentId", "Instrument identity is required for this transaction kind.");
  }

  if (typeof input.occurredAt !== "string" || !input.occurredAt.trim() || !Number.isFinite(Date.parse(input.occurredAt))) {
    addIssue("occurredAt", "A valid transaction date/time is required.");
  }

  if (typeof input.currency !== "string" || !/^[A-Z]{3}$/.test(input.currency)) {
    addIssue("currency", "Currency must be a three-letter uppercase code such as INR.");
  }

  if (["buy", "sell", "opening-balance"].includes(kind)) {
    if (!isPositiveFiniteNumber(input.quantity)) {
      addIssue("quantity", "Quantity must be a finite positive number.");
    }
  }

  if (kind === "buy" || kind === "sell") {
    if (!isPositiveFiniteNumber(input.unitPrice)) {
      addIssue("unitPrice", "Buy and sell transactions require a finite positive unit price.");
    }
  }

  if (kind === "opening-balance" && input.unitPrice !== undefined && !isPositiveFiniteNumber(input.unitPrice)) {
    addIssue("unitPrice", "If supplied, opening cost per unit must be a finite positive number.");
  }

  if (kind === "fee" || kind === "dividend") {
    if (!isPositiveFiniteNumber(input.amount)) {
      addIssue("amount", "Fee and dividend rows require a finite positive amount.");
    }
  }

  if (input.charges !== undefined && !isNonNegativeFiniteNumber(input.charges)) {
    addIssue("charges", "Charges must be a finite non-negative number.");
  }

  if (!isRecord(input.source)) {
    addIssue("source", "Source filename and row number are required.");
  } else {
    if (typeof input.source.fileName !== "string" || !input.source.fileName.trim()) {
      addIssue("source.fileName", "Source filename is required.");
    }
    if (
      typeof input.source.rowNumber !== "number" ||
      !Number.isInteger(input.source.rowNumber) ||
      input.source.rowNumber < 1
    ) {
      addIssue("source.rowNumber", "Source row number must be a positive integer.");
    }
  }

  if (issues.length > 0) {
    return { status: "invalid", issues };
  }

  // Fields are narrowed by the checks above; optional values are retained as supplied.
  const transaction: CanonicalTransaction = {
    transactionId: input.transactionId as string,
    kind,
    occurredAt: input.occurredAt as string,
    currency: input.currency as string,
    source: input.source as TransactionSource,
  };

  if (typeof instrumentId === "string") transaction.instrumentId = instrumentId;
  if (typeof input.quantity === "number") transaction.quantity = input.quantity;
  if (typeof input.unitPrice === "number") transaction.unitPrice = input.unitPrice;
  if (typeof input.amount === "number") transaction.amount = input.amount;
  if (typeof input.charges === "number") transaction.charges = input.charges;

  return { status: "valid", transaction };
}
